 g=read(ROOT/'output/plausibility-geometry.json');dep=read(ROOT/'output/plausibility-deposition.json');extra=read(ROOT/'output/plausibility-service-details.json');assembly=read(ROOT/'output/assembly-export-check.json');exp=read(ROOT/'output/plausibility-export-readbacks.json');prep=read(ROOT/'print-rest/Bett-01/preparation.json')
 assert g['installed_prints']['status']=='PASS' and all(r['status']=='PASS'for r in g['actual_risers'])
