 assert dep['three_mf_sha256']=='b093e5041a4af816f4e3f11af4ddcb438ec5aa9518182b90b5f8d0b5573d3faf'
 report=dict(revision='PI-2L-5',audit_revision='PLAUSIBILITY-1',status='PASS_SCOPED_NOMINAL_GEOMETRY_WITH_SERVICE_CONDITIONS',complete_functional_acceptance=False,print_start=False,print_geometry_changed=False,scope='31-part inner-build rest bed. Existing outer case and old lower-tray box-fixing defect excluded. No electrical or physical acceptance.',source_sha256=sha(ROOT/'design.json'),mechanical_sha256=sha(ROOT/'output/rest-mechanical.json'),assembly_step_sha256=assembly['assembly_step_sha256'],gcode_sha256=dep['gcode_sha256'],three_mf_sha256=dep['three_mf_sha256'],findings=[dict(id='SERVICE_POWER',status='RESOLVED_NOMINAL_PROCEDURE',instruction='Open stack on bench: unplug +X26mm, hold connector +X26/Y-50mm in front; lift upper level +Z60mm. Do not push connector down through tray. Flexible lower loom length, bends and manual feeding remain OPEN.'),dict(id='GPIO_REAR_SLOT',status='RESOLVED_NOMINAL_ALTERNATIVE_ROUTE',instruction='2.5mm rear slot probe collides with bridge; do not use narrowed slot. Use external rear bridge wrap for second tie, front slot for body tie. Actual tie/buckle/isolated-tail bundle and holding force remain OPEN.')],support_review=dict(status='PASS_SCOPED_VISUAL_OPEN_ACCESS',supported_body_count=7,scope='Actual sliced 3D and first-layer image reviewed internally. Riser sockets, adapter nut pockets and collars printed without support. Access to support on open decks/rails observed; no breakaway-force or damage proof.',physical_removal='OPEN'),thin_structures=dict(status='OPEN_PHYSICAL_STIFFNESS_AND_PETG_CREEP',nominal_features_mm=[1.3,1.6,2],scope='Four walls is a profile setting, not four lines in every thin lip/web. Sideways carrier orientation and supported horizontal decks retained. No load-specific FEA or strength certification.'),physical_trials=[dict(parts='1 Wandleradapter + 2 gedruckte Isolierscheiben',check='Originalstützen und richtige Lochdiagonale ohne Zwang zusammenfügen; Muttern einsetzen und entnehmen; M3×8-Länge, Isolation, Kupferfreiheit und Platinenunterseite prüfen.'),dict(parts='1 Ebenenstütze',check='Haftband entfernen; Zapfen, Aufnahme, M3-Schraubeneinsetzen, Werkzeugzugang und Mutterdach prüfen. Festziehen ohne Risse oder Abheben der Platte.'),dict(parts='2-, 3-, 4-poliger YC100 sowie Power-/CAN-Codierung',check='Reale Steckerkörper, Lötstift-Isolation, Stecken, Abziehen und Zugentlastung prüfen. GPIO-Schlaufe mit vorhandenem 104×2,5-mm-Binder erproben.'),dict(parts='Gestützte Träger und vollständiges Gerüst',check='PETG-Stützen ohne Beschädigung entfernen; Querbohrungen, Kabelreserve beim Ausbau und tatsächliche USB-Längen/-Bögen prüfen. Danach Gerüststeifigkeit bei der vorgesehenen Handhabung testen.'),dict(parts='Vollständig verdrahtete Baugruppe',check='Später getrennt Durchgang, Polung, Sicherungs-/Diodenpfade, USB-Rückspeisung, Kontaktstrom und Spannungsfall, Wandler-Lastteilung, Einschalten und Temperaturen unter höchster vorgesehener Last prüfen. Dieser Bericht erteilt keine Einschaltfreigabe.')],research_sources=[dict(title=t,url=u)for t,u in SOURCES])
