 pdf=OUT/'Plausibilitaet-PI-2L-5.pdf';c=canvas.Canvas(str(pdf),pagesize=A4);c.setTitle('Pi-Box PI-2L-5 | Plausibilitätsprüfung');W,H=A4;style=ParagraphStyle('body',fontName='Helvetica',fontSize=9.5,leading=13,textColor=colors.HexColor('#243747'));small=ParagraphStyle('small',parent=style,fontSize=8,leading=10.5)
 def para(text,y,sty=style):
  p=Paragraph(text,sty);_,h=p.wrap(W-88,H);p.drawOn(c,44,y-h);return y-h-9
 def page(title,num):
  c.setFillColor(colors.HexColor('#14394b'));c.setFont('Helvetica-Bold',19);c.drawString(44,H-54,title);c.setFont('Helvetica',9);c.setFillColor(colors.HexColor('#556b78'));c.drawString(44,H-74,'PI-2L-5 · Prüfstand PLAUSIBILITY-1 · 31 Druckkörper / 15 Typen')
  c.setFont('Helvetica',8);c.drawString(44,28,'Digitaler Modellnachweis; reale Passung, Festigkeit und Betrieb bleiben getrennt.');c.drawRightString(W-44,28,f'{num} / 2');return H-98
 y=page('Pi-Box: Ergebnis der Prüfung',1)
 y=para('<b>Ergebnis:</b> Die vorhandene Bettdatei bleibt unverändert. Für die geprüften nominalen Geometrien ist kein Neudruck-Entwurf nötig. Zwei konkrete Montagehinweise gelten verbindlich. Eine vollständige Funktions- oder Betriebsfreigabe ist damit noch nicht belegt.',y)
 rows=[['Prüfung','Beleg und praktische Bedeutung'],['Dateien und Quellen','211 BRep-Quellen an Hashes geprüft. 15 STEP/STL/3MF-Typen gültig, geschlossen, ein Körper, Millimeter. Gesamt-STEP mit korrigierten Wandlern neu erstellt und zurückgelesen: 2.996 Festkörper.'],['Einbau und Befestigung','144 exakte Kandidatenprüfungen an 21 eingebauten Druckteilen: keine ungewollte Überschneidung; vier vorgesehene M2/PETG-Eingriffe. Vier tatsächliche Stützen: Schrauben-/Muttereinsetzen und Werkzeugweg frei; Mutter wird vom Dach gehalten.'],['Druckbahnen und Bett','Alle 31 Körper und 50 Bohrkanäle im G-Code vorhanden. Zwölf horizontale M3-Kanäle mit Linienbreite/-höhe geprüft: nominal 3,200–3,212 mm frei. Materialhülle einschließlich Stützen/Brim innerhalb 220 × 220 mm; kleinster Rand 0,532 mm.'],['Stecker, USB, Wartung','11 Steckpaare an je sechs Abziehpositionen frei. Zwei USB-Referenzwege: 400 Abstandstests ohne Kollision. Oberplattenhub um 60 mm in 0,5-mm-Schritten frei, wenn Ebenenstecker zuvor nach vorn geparkt ist. Keine lückenlose Prüfung realer flexibler Adern.']]
 table=Table([[Paragraph(html.escape(a),small),Paragraph(html.escape(b),small)]for a,b in rows],colWidths=[108,W-196],hAlign='LEFT');table.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e5eef1')),('VALIGN',(0,0),(-1,-1),'TOP'),('BOX',(0,0),(-1,-1),.5,colors.HexColor('#afc0c8')),('INNERGRID',(0,0),(-1,-1),.3,colors.HexColor('#ccd7dc')),('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7)]));_,hh=table.wrap(W-88,H);table.drawOn(c,44,y-hh);y-=hh+16
