 y=para('<b>Stützen und dünne Bereiche:</b> Sieben Körper benötigen Stützen; die offene Zugänglichkeit wurde an den tatsächlichen Slicer-Bildern geprüft. PETG-Stützen können fest haften. Entfernbarkeit ohne Bruch, Gewindehaltevermögen und Dauerverformung bleiben real offen. 1,3–2-mm-Lippen und Stege haben nicht automatisch vier Wandbahnen. Ohne belastbare Lasten wird keine Festigkeitsberechnung vorgetäuscht.',y)
 y=para('<b>Quellen für die Prüfkriterien</b> (Hersteller-/Fachunterlagen, geprüft am 30.10.2026)',y)
 for title,url in SOURCES:y=para(f'<link href="{url}" color="#17627e">{html.escape(title)}</link>',y,small)
 y=para('<b>Quellenbindung</b><br/>Modell: '+report['source_sha256'][:20]+'…<br/>STEP: '+report['assembly_step_sha256'][:20]+'…<br/>G-Code unverändert: '+report['gcode_sha256'][:20]+'…<br/>Vollständige Hashes und Einzelnachweise: Plausibilitaet-PI-2L-5.json im selben Ordner.',y,small)
 y=para('Außenhülle und der bekannte Fehler der alten unteren Gehäuseverschraubung sind nicht Teil dieses Auftrags. Alte Fehlversuche bleiben erhalten. Keine Datei wurde zum Drucker übertragen, kein Druck gestartet und kein Materialverbrauch gebucht.',y,small)
 assert y>48,y;c.save();print('REPORT',pdf,flush=True)
